import{_ as c,C as t,o as r,c as d,a4 as e,b as o,w as s,a as p,E as i,a5 as h,j as f}from"./chunks/framework.BUqnS5H7.js";const _=JSON.parse('{"title":"副本与 ISR","description":"","frontmatter":{},"headers":[],"relativePath":"kafka/02-core/chapter-04-replication-and-isr.md","filePath":"kafka/02-core/chapter-04-replication-and-isr.md"}'),k={name:"kafka/02-core/chapter-04-replication-and-isr.md"},m={"data-src-line":"158","data-src-file":"kafka/02-core/chapter-04-replication-and-isr.md"};function u(g,a,L,b,q,E){const n=t("Mermaid"),l=t("SvgDiagram");return r(),d("div",null,[a[1]||(a[1]=e(`<h1 id="副本与-isr" tabindex="-1" data-src-line="1" data-src-file="kafka/02-core/chapter-04-replication-and-isr.md">副本与 ISR <a class="header-anchor" href="#副本与-isr" aria-label="Permalink to &quot;副本与 ISR&quot;">​</a></h1><blockquote data-src-line="3" data-src-file="kafka/02-core/chapter-04-replication-and-isr.md"><p data-src-line="3" data-src-file="kafka/02-core/chapter-04-replication-and-isr.md">副本机制是 Kafka 可靠性的物理基础。但&quot;多存几份&quot;只是表象——真正的难点在于：多个副本之间怎么保持同步？谁来决定哪些副本&quot;够格&quot;？Leader 宕机时怎么选新 Leader 而不丢数据？这些问题的答案都指向一个核心概念：ISR（In-Sync Replicas）。</p></blockquote><h2 id="_1-从一个最基本的问题开始" tabindex="-1" data-src-line="5" data-src-file="kafka/02-core/chapter-04-replication-and-isr.md">1. 从一个最基本的问题开始 <a class="header-anchor" href="#_1-从一个最基本的问题开始" aria-label="Permalink to &quot;1. 从一个最基本的问题开始&quot;">​</a></h2><p data-src-line="7" data-src-file="kafka/02-core/chapter-04-replication-and-isr.md">假设你有一个 Partition，消息只存在一台 Broker 上。这台 Broker 的磁盘坏了，数据永久丢失。</p><p data-src-line="9" data-src-file="kafka/02-core/chapter-04-replication-and-isr.md">最直觉的解法：多存几份。把同样的数据复制到 3 台 Broker 上，坏了一台还有两台。</p><p data-src-line="11" data-src-file="kafka/02-core/chapter-04-replication-and-isr.md">但这个&quot;复制&quot;不是简单的拷贝。你需要回答一连串问题：</p><ul data-src-line="13" data-src-file="kafka/02-core/chapter-04-replication-and-isr.md"><li data-src-line="13" data-src-file="kafka/02-core/chapter-04-replication-and-isr.md">谁来处理读写请求？三个副本都能接请求吗？</li><li data-src-line="14" data-src-file="kafka/02-core/chapter-04-replication-and-isr.md">如果三个副本都能接写入，写入顺序怎么保证？</li><li data-src-line="15" data-src-file="kafka/02-core/chapter-04-replication-and-isr.md">Follower 复制数据的速度跟不上 Leader 怎么办？</li><li data-src-line="16" data-src-file="kafka/02-core/chapter-04-replication-and-isr.md">Leader 宕机了，从剩下的副本里选新 Leader，选谁？怎么选？</li></ul><p data-src-line="18" data-src-file="kafka/02-core/chapter-04-replication-and-isr.md">Kafka 对这些问题的回答构成了它的副本模型：<strong>Leader 独占读写，Follower 只管复制，ISR 管理同步状态</strong>。</p><h2 id="_2-为什么读写必须只走-leader" tabindex="-1" data-src-line="20" data-src-file="kafka/02-core/chapter-04-replication-and-isr.md">2. 为什么读写必须只走 Leader <a class="header-anchor" href="#_2-为什么读写必须只走-leader" aria-label="Permalink to &quot;2. 为什么读写必须只走 Leader&quot;">​</a></h2><p data-src-line="22" data-src-file="kafka/02-core/chapter-04-replication-and-isr.md">这是 Kafka 副本模型的第一个关键决策。如果允许多个副本同时接写入：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Producer A → Broker 1（Leader）: 写入 msg1</span></span>
<span class="line"><span>Producer B → Broker 2（Follower）: 写入 msg2</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Broker 1 的日志: [msg1, msg2]</span></span>
<span class="line"><span>Broker 2 的日志: [msg2, msg1]  ← 顺序反了</span></span></code></pre></div><p data-src-line="32" data-src-file="kafka/02-core/chapter-04-replication-and-isr.md">两个副本的写入顺序无法保证一致——没有全局时钟，网络延迟也不同。顺序一旦分叉，消费者从不同副本读到的数据就不一样，一致性彻底崩溃。</p><p data-src-line="34" data-src-file="kafka/02-core/chapter-04-replication-and-isr.md">如果允许 Follower 接读：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Consumer → Broker 2（Follower）: 读取 offset 100</span></span>
<span class="line"><span>但 Broker 2 还没从 Leader 同步到 offset 100</span></span>
<span class="line"><span>→ Consumer 读不到，或者读到旧数据</span></span></code></pre></div><p data-src-line="42" data-src-file="kafka/02-core/chapter-04-replication-and-isr.md">所以 Kafka 的选择是：<strong>Leader 独占读写，Follower 只做一件事——从 Leader 拉数据</strong>。这个设计牺牲了读写负载均衡，换来了最简单的一致性保证。</p><h2 id="_3-leo-和-hw-两个关键偏移量" tabindex="-1" data-src-line="44" data-src-file="kafka/02-core/chapter-04-replication-and-isr.md">3. LEO 和 HW：两个关键偏移量 <a class="header-anchor" href="#_3-leo-和-hw-两个关键偏移量" aria-label="Permalink to &quot;3. LEO 和 HW：两个关键偏移量&quot;">​</a></h2><p data-src-line="46" data-src-file="kafka/02-core/chapter-04-replication-and-isr.md">LEO 由每个副本各自维护；HW 则由 Leader 统一计算。这两个偏移量决定了&quot;消费者能看到哪些数据&quot;：</p><p data-src-line="48" data-src-file="kafka/02-core/chapter-04-replication-and-isr.md"><strong>LEO（Log End Offset）</strong>：本地日志末尾的下一个待写入位置。换句话说，这个副本已经写到了哪。</p><p data-src-line="50" data-src-file="kafka/02-core/chapter-04-replication-and-isr.md"><strong>HW（High Watermark）</strong>：所有<strong>同步副本</strong>中最小的 LEO。换句话说，&quot;确认所有同步副本都已经写入&quot;的边界。它全局只有一个值，且只有 Leader 计算——Leader 掌握所有同步副本的 LEO，取最小即可。Follower 本地也有一个 HW 字段，但不是自己算的，而是 Leader 在下一次 Fetch 响应中捎带过去的。这个捎带有延迟，所以同一时刻各副本本地存的 HW 可能不一致：概念上只有一个，物理上每个副本各存一份。</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Leader LEO = 150</span></span>
<span class="line"><span>Follower A LEO = 148</span></span>
<span class="line"><span>Follower B LEO = 145</span></span>
<span class="line"><span></span></span>
<span class="line"><span>HW = min(150, 148, 145) = 145</span></span></code></pre></div><p data-src-line="60" data-src-file="kafka/02-core/chapter-04-replication-and-isr.md"><strong>消费者只能读到 HW 之前的消息</strong>。为什么？因为 HW 之前的消息意味着&quot;所有同步副本都已写入&quot;——即使 Leader 立刻宕机，切换到任意同步副本，这些消息都还在。HW 之后的消息只存在于部分副本中，如果现在让消费者读到，Leader 宕机后这条消息可能丢失，消费者已经处理了但数据没了，这就是数据不一致。</p><p data-src-line="62" data-src-file="kafka/02-core/chapter-04-replication-and-isr.md">HW 的设计是 Kafka 可靠性的核心：它在&quot;消费者能看到的数据&quot;和&quot;所有副本都确认的数据&quot;之间画了一条线。</p><h2 id="isr-definition" tabindex="-1" data-src-line="64" data-src-file="kafka/02-core/chapter-04-replication-and-isr.md">4. ISR：哪些副本&quot;够格&quot; <a class="header-anchor" href="#isr-definition" aria-label="Permalink to &quot;4. ISR：哪些副本&quot;够格&quot; {#isr-definition}&quot;">​</a></h2><p data-src-line="66" data-src-file="kafka/02-core/chapter-04-replication-and-isr.md"><strong>ISR（In-Sync Replicas）是一份动态名单：记录当前与 Leader 保持同步的副本，Leader 自身也在名单内。它决定两件事——<code>acks=all</code> 写入要等谁确认、Leader 宕机后从谁中选新 Leader。</strong></p><p data-src-line="68" data-src-file="kafka/02-core/chapter-04-replication-and-isr.md">不是所有 Follower 都有资格参与 HW 的计算。只有 <strong>ISR（In-Sync Replicas）</strong> 中的副本才被算在内。</p><p data-src-line="70" data-src-file="kafka/02-core/chapter-04-replication-and-isr.md">ISR 是&quot;与 Leader 保持同步的副本集合&quot;，包含 Leader 自身。Leader 为每个 Follower 记录一个时间戳 <code>lastCaughtUpTimeMs</code>——该 Follower 上一次完全追上 Leader LEO 的时刻。是否留在 ISR 取决于时间窗口，而非实时比较：Follower 在 <code>replica.lag.time.max.ms</code>（默认 30 秒）内追平过 Leader 的 LEO，就仍在 ISR；一旦 <code>当前时间 - lastCaughtUpTimeMs</code> 超过该阈值，才被移出。</p><p data-src-line="72" data-src-file="kafka/02-core/chapter-04-replication-and-isr.md">这里容易误解：<strong>&quot;追上&quot;指 <code>follower.LEO &gt;= leader.LEO</code>，而非追到 <code>leader.HW</code>，也非每时每刻都必须相等</strong>。Leader 的 LEO 在持续写入时不断前进，Follower 无需时刻追平——只要它的拉取速度不低于 Leader 的写入速度，就会周期性追平一次，每次追平都刷新 <code>lastCaughtUpTimeMs</code>。只有长期追不上（时间窗口内从未追平）才会被移出 ISR。</p><p data-src-line="74" data-src-file="kafka/02-core/chapter-04-replication-and-isr.md">ISR 是动态的：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>正常：ISR = {Leader, Follower1, Follower2}</span></span>
<span class="line"><span>Follower2 变慢：ISR = {Leader, Follower1}（Follower2 被移出）</span></span>
<span class="line"><span>Follower2 恢复：ISR = {Leader, Follower1, Follower2}（重新加入）</span></span></code></pre></div><p data-src-line="82" data-src-file="kafka/02-core/chapter-04-replication-and-isr.md">ISR 收缩意味着&quot;确认写入成功的副本数减少&quot;。如果 ISR 收缩到只剩 Leader，配合 <code>min.insync.replicas=2</code>，Broker 会拒绝 <code>acks=all</code> 的写入——因为 ISR 中的副本数不足。</p><h2 id="_5-acks-all-的完整时序" tabindex="-1" data-src-line="84" data-src-file="kafka/02-core/chapter-04-replication-and-isr.md">5. acks=all 的完整时序 <a class="header-anchor" href="#_5-acks-all-的完整时序" aria-label="Permalink to &quot;5. acks=all 的完整时序&quot;">​</a></h2><p data-src-line="86" data-src-file="kafka/02-core/chapter-04-replication-and-isr.md">理解了 LEO、HW、ISR，才能真正理解 <code>acks=all</code> 的含义：</p>`,32)),(r(),o(h,null,{default:s(()=>[i(n,{id:"mermaid-109",class:"mermaid",graph:"sequenceDiagram%0A%20%20%20%20participant%20P%20as%20Producer%0A%20%20%20%20participant%20L%20as%20Leader%0A%20%20%20%20participant%20A%20as%20Follower%20A%0A%20%20%20%20participant%20B%20as%20Follower%20B%0A%0A%20%20%20%20P-%3E%3EL%3A%20ProduceReq%20acks%3Dall%0A%20%20%20%20L-%3E%3EL%3A%20%E5%86%99%E5%85%A5%E6%9C%AC%E5%9C%B0%E6%97%A5%E5%BF%97%EF%BC%8CLEO%20%E5%89%8D%E8%BF%9B%0A%20%20%20%20L-%3E%3EL%3A%20%E6%8C%82%E8%B5%B7%20DelayedProduce%EF%BC%88%E4%B8%8D%E7%AB%8B%E5%88%BB%E8%BF%94%E5%9B%9E%EF%BC%89%0A%20%20%20%20A-%3E%3EL%3A%20Fetch(replicaId%3DA)%0A%20%20%20%20B-%3E%3EL%3A%20Fetch(replicaId%3DB)%0A%20%20%20%20L-%3E%3EL%3A%20%E6%9B%B4%E6%96%B0%20HW%20%3D%20min(ISR.LEO)%0A%20%20%20%20L-%3E%3EL%3A%20HW%20%3E%3D%20%E7%9B%AE%E6%A0%87%20offset%EF%BC%8C%E5%94%A4%E9%86%92%20DelayedProduce%0A%20%20%20%20L--%3E%3EP%3A%20ProduceResp%20OK%0A"})]),fallback:s(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e(`<p data-src-line="105" data-src-file="kafka/02-core/chapter-04-replication-and-isr.md"><code>acks=all</code> 的语义是：<strong>消息写入所有 ISR 副本后才算成功</strong>。它不是等所有副本都写入——OSR（落后的副本）不算在内。这就是为什么 ISR 的管理如此重要：ISR 太大，写入延迟高；ISR 太小，可靠性下降。</p><h2 id="_6-leader-epoch-为什么不能只靠-hw-做截断" tabindex="-1" data-src-line="107" data-src-file="kafka/02-core/chapter-04-replication-and-isr.md">6. Leader Epoch：为什么不能只靠 HW 做截断 <a class="header-anchor" href="#_6-leader-epoch-为什么不能只靠-hw-做截断" aria-label="Permalink to &quot;6. Leader Epoch：为什么不能只靠 HW 做截断&quot;">​</a></h2><p data-src-line="109" data-src-file="kafka/02-core/chapter-04-replication-and-isr.md">先划清边界：<strong>Leader Epoch 解决的是&quot;副本之间日志如何对齐&quot;的问题，与消费者如何消费消息无关。</strong> 消费者能读到哪条消息，只取决于该消息是否越过 HW（§3）；Leader 是否换届、epoch 如何变化，都不改变消费者的读进度。Leader Epoch 只在一个副本重启回来、需要把本地多出的分叉日志截断一部分以对齐新 Leader 时生效。</p><h3 id="_6-1-问题-截断到哪才算准" tabindex="-1" data-src-line="111" data-src-file="kafka/02-core/chapter-04-replication-and-isr.md">6.1 问题：截断到哪才算准 <a class="header-anchor" href="#_6-1-问题-截断到哪才算准" aria-label="Permalink to &quot;6.1 问题：截断到哪才算准&quot;">​</a></h3><p data-src-line="113" data-src-file="kafka/02-core/chapter-04-replication-and-isr.md">一个副本（旧 Leader 或掉队的 Follower）重启后，本地日志可能比新 Leader 多出一段分叉数据，必须截断。唯一的问题是：<strong>截断到哪才算准。</strong></p><p data-src-line="115" data-src-file="kafka/02-core/chapter-04-replication-and-isr.md">旧方案按副本本地的 HW 截断，但 HW 是滞后的值（只在 Fetch 响应中更新），可能把&quot;其实已确认&quot;的消息误删。看这个例子——B 是 Leader，A 是 Follower：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>T1: B 写入 m1、m2，B 的 LEO = 2</span></span>
<span class="line"><span>    A 已拉取到 m2，A 的 LEO = 2</span></span>
<span class="line"><span>    但 A 尚未收到 B 发来的新 HW，A 本地 HW 仍 = 1</span></span>
<span class="line"><span>T2: A 重启</span></span>
<span class="line"><span>    旧规则：按本地 HW = 1 截断 → m2 被删</span></span>
<span class="line"><span>T3: B 宕机，A 当选新 Leader</span></span>
<span class="line"><span>    m2 已被 A 误删，永久丢失</span></span></code></pre></div><p data-src-line="127" data-src-file="kafka/02-core/chapter-04-replication-and-isr.md">根源在于：HW 滞后于实际同步进度，用它做截断决策不可靠。</p><h3 id="_6-2-epoch-是什么" tabindex="-1" data-src-line="129" data-src-file="kafka/02-core/chapter-04-replication-and-isr.md">6.2 epoch 是什么 <a class="header-anchor" href="#_6-2-epoch-是什么" aria-label="Permalink to &quot;6.2 epoch 是什么&quot;">​</a></h3><p data-src-line="131" data-src-file="kafka/02-core/chapter-04-replication-and-isr.md"><strong>epoch 本身是一个单调递增的整数，每次 Leader 换届就 +1，标记日志的&quot;任期&quot;</strong>——每条消息都能追溯到是哪一任 Leader 期间写入的。</p><p data-src-line="133" data-src-file="kafka/02-core/chapter-04-replication-and-isr.md">但光有整数还不够定位。为找到两条日志的&quot;公共前缀&quot;，Kafka 还要为每个 epoch 记录它上任时的起始 offset，形成 <code>epoch → startOffset</code> 的映射，把日志切成一段段：<code>epoch=1</code> 对应 offset 0~99，<code>epoch=2</code> 对应 offset 100~150。</p><h3 id="_6-3-新的截断协议" tabindex="-1" data-src-line="135" data-src-file="kafka/02-core/chapter-04-replication-and-isr.md">6.3 新的截断协议 <a class="header-anchor" href="#_6-3-新的截断协议" aria-label="Permalink to &quot;6.3 新的截断协议&quot;">​</a></h3><p data-src-line="137" data-src-file="kafka/02-core/chapter-04-replication-and-isr.md"><strong>Leader Epoch</strong>（<a href="https://cwiki.apache.org/confluence/display/KAFKA/KIP-101" target="_blank" rel="noreferrer">KIP-101</a>）让 Follower 不再凭本地 HW 猜测，而是直接问 Leader。协议三步：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. Follower 重启，向 Leader 报告：&quot;我日志里最后一次是在第 X 任 Leader 下写的&quot;</span></span>
<span class="line"><span>2. Leader 查自己的 epoch 记录，返回 endOffset：</span></span>
<span class="line"><span>   - 若 X 是 Leader 当前这一任 → 返回 Leader 的 LEO（双方同代，无需截断）</span></span>
<span class="line"><span>   - 若 X 是更早的任 → 返回&quot;第 X 任之后那一任的 startOffset&quot;（截断跨代多出的部分）</span></span>
<span class="line"><span>3. Follower 把本地 LEO 大于返回值的部分截断，然后正常拉取对齐</span></span></code></pre></div><p data-src-line="147" data-src-file="kafka/02-core/chapter-04-replication-and-isr.md">回到 6.1 的例子，新协议下的结果：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>A 重启后问 B：&quot;我最后一次是第几任写的&quot;（双方同代，epoch 都是 0）</span></span>
<span class="line"><span>B 答：&quot;你我同代，我的 LEO = 2&quot;</span></span>
<span class="line"><span>A 的 LEO = 2，无需截断，m2 保留</span></span>
<span class="line"><span>之后 B 宕机，A 当选新 Leader，m2 不丢</span></span></code></pre></div><p data-src-line="156" data-src-file="kafka/02-core/chapter-04-replication-and-isr.md">关键在于第 2 步：Leader 用 epoch 精确定位&quot;两条日志的公共前缀在哪里&quot;。epoch 单调递增，公共前缀必然是某个 epoch 的边界，比用可能过时的 HW 可靠得多。</p>`,17)),f("p",m,[i(l,{src:"/kafka/02-core-chapter-04-leader-epoch.svg",alt:"Leader Epoch 截断机制对比"})]),a[3]||(a[3]=e(`<h2 id="leader-election" tabindex="-1" data-src-line="160" data-src-file="kafka/02-core/chapter-04-replication-and-isr.md">7. Leader 选举 <a class="header-anchor" href="#leader-election" aria-label="Permalink to &quot;7. Leader 选举 {#leader-election}&quot;">​</a></h2><h3 id="_7-1-正常选举" tabindex="-1" data-src-line="162" data-src-file="kafka/02-core/chapter-04-replication-and-isr.md">7.1 正常选举 <a class="header-anchor" href="#_7-1-正常选举" aria-label="Permalink to &quot;7.1 正常选举&quot;">​</a></h3><p data-src-line="164" data-src-file="kafka/02-core/chapter-04-replication-and-isr.md">Leader 所在 Broker 宕机后，Controller 从当前 ISR 中选第一个成员作为新 Leader。为什么是 ISR？因为 ISR 中的副本与 Leader 同步，选它不会丢数据。为什么是&quot;第一个&quot;？因为副本列表的顺序是创建时确定的，第一个成员就是 preferred replica，选它有利于负载均衡。</p><h3 id="unclean-leader-election" tabindex="-1" data-src-line="166" data-src-file="kafka/02-core/chapter-04-replication-and-isr.md">7.2 Unclean Leader 选举 <a class="header-anchor" href="#unclean-leader-election" aria-label="Permalink to &quot;7.2 Unclean Leader 选举 {#unclean-leader-election}&quot;">​</a></h3><p data-src-line="168" data-src-file="kafka/02-core/chapter-04-replication-and-isr.md">如果 ISR 为空呢？所有同步副本都挂了，只剩下 OSR（落后的副本）。这时候有两个选择：</p><ul data-src-line="170" data-src-file="kafka/02-core/chapter-04-replication-and-isr.md"><li data-src-line="170" data-src-file="kafka/02-core/chapter-04-replication-and-isr.md"><strong>禁止 Unclean 选举</strong>：分区不可用，等 ISR 成员恢复。不丢数据，但服务中断。</li><li data-src-line="171" data-src-file="kafka/02-core/chapter-04-replication-and-isr.md"><strong>允许 Unclean 选举</strong>：从 OSR 中选 Leader。服务可用，但 OSR 副本中缺失的数据永久丢失。</li></ul><p data-src-line="173" data-src-file="kafka/02-core/chapter-04-replication-and-isr.md"><code>unclean.leader.election.enable=false</code>（推荐）意味着宁可不可用也不丢数据。这个选择取决于你的业务：金融交易不能丢数据，日志收集可以容忍少量丢失。</p><h2 id="_8-isr-变更的传播" tabindex="-1" data-src-line="175" data-src-file="kafka/02-core/chapter-04-replication-and-isr.md">8. ISR 变更的传播 <a class="header-anchor" href="#_8-isr-变更的传播" aria-label="Permalink to &quot;8. ISR 变更的传播&quot;">​</a></h2><p data-src-line="177" data-src-file="kafka/02-core/chapter-04-replication-and-isr.md">ISR 变更不是 Leader 自己说了算。Leader 发起变更请求（<code>AlterPartitionRequest</code>），但最终决定权在 Controller：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Leader → Controller: &quot;ISR 变了，新 ISR 是 {我, F1}&quot;</span></span>
<span class="line"><span>Controller: 校验后写入元数据日志</span></span>
<span class="line"><span>Controller → 所有 Broker: 广播变更</span></span></code></pre></div><p data-src-line="185" data-src-file="kafka/02-core/chapter-04-replication-and-isr.md">为什么要绕这一圈？因为 ISR 状态必须在 Leader 换届过程中也保持全局一致。如果 Leader 自己管理 ISR，两个 Broker 可能同时认为自己是 Leader，各自维护了不同的 ISR，集群就会出现&quot;脑裂&quot;。Controller 是唯一权威源，保证 ISR 状态的全局一致性。</p><h2 id="_9-关键配置" tabindex="-1" data-src-line="187" data-src-file="kafka/02-core/chapter-04-replication-and-isr.md">9. 关键配置 <a class="header-anchor" href="#_9-关键配置" aria-label="Permalink to &quot;9. 关键配置&quot;">​</a></h2><table tabindex="0"><thead data-src-line="189" data-src-file="kafka/02-core/chapter-04-replication-and-isr.md"><tr data-src-line="189" data-src-file="kafka/02-core/chapter-04-replication-and-isr.md"><th style="text-align:left;">参数</th><th style="text-align:left;">为什么这样设</th></tr></thead><tbody data-src-line="191" data-src-file="kafka/02-core/chapter-04-replication-and-isr.md"><tr data-src-line="191" data-src-file="kafka/02-core/chapter-04-replication-and-isr.md"><td style="text-align:left;"><code>default.replication.factor=3</code></td><td style="text-align:left;">3 副本是可靠性和成本的平衡点——坏了一台还有两台</td></tr><tr data-src-line="192" data-src-file="kafka/02-core/chapter-04-replication-and-isr.md"><td style="text-align:left;"><code>min.insync.replicas=2</code></td><td style="text-align:left;">配合 acks=all，保证至少两个副本有数据</td></tr><tr data-src-line="193" data-src-file="kafka/02-core/chapter-04-replication-and-isr.md"><td style="text-align:left;"><code>unclean.leader.election.enable=false</code></td><td style="text-align:left;">宁可不可用也不丢数据</td></tr><tr data-src-line="194" data-src-file="kafka/02-core/chapter-04-replication-and-isr.md"><td style="text-align:left;"><code>replica.lag.time.max.ms=30000</code></td><td style="text-align:left;">保持默认。调小会因 GC 停顿、网络抖动触发 spurious shrink</td></tr></tbody></table><h2 id="_10-监控" tabindex="-1" data-src-line="196" data-src-file="kafka/02-core/chapter-04-replication-and-isr.md">10. 监控 <a class="header-anchor" href="#_10-监控" aria-label="Permalink to &quot;10. 监控&quot;">​</a></h2><table tabindex="0"><thead data-src-line="198" data-src-file="kafka/02-core/chapter-04-replication-and-isr.md"><tr data-src-line="198" data-src-file="kafka/02-core/chapter-04-replication-and-isr.md"><th style="text-align:left;">指标</th><th style="text-align:left;">含义</th><th style="text-align:left;">为什么重要</th></tr></thead><tbody data-src-line="200" data-src-file="kafka/02-core/chapter-04-replication-and-isr.md"><tr data-src-line="200" data-src-file="kafka/02-core/chapter-04-replication-and-isr.md"><td style="text-align:left;"><code>UnderReplicatedPartitions</code></td><td style="text-align:left;">ISR 少于 RF 的分区数</td><td style="text-align:left;">&gt; 0 说明有副本掉队</td></tr><tr data-src-line="201" data-src-file="kafka/02-core/chapter-04-replication-and-isr.md"><td style="text-align:left;"><code>UnderMinIsrPartitionCount</code></td><td style="text-align:left;">ISR 少于 min.insync.replicas 的分区数</td><td style="text-align:left;">&gt; 0 说明 acks=all 已开始拒写</td></tr><tr data-src-line="202" data-src-file="kafka/02-core/chapter-04-replication-and-isr.md"><td style="text-align:left;"><code>IsrShrinksPerSec</code></td><td style="text-align:left;">ISR 收缩频率</td><td style="text-align:left;">频繁抖动说明参数与实际不匹配</td></tr><tr data-src-line="203" data-src-file="kafka/02-core/chapter-04-replication-and-isr.md"><td style="text-align:left;"><code>UncleanLeaderElectionsPerSec</code></td><td style="text-align:left;">Unclean 选举次数</td><td style="text-align:left;">&gt; 0 意味着真实的数据丢失</td></tr></tbody></table><p data-src-line="205" data-src-file="kafka/02-core/chapter-04-replication-and-isr.md">ISR 频繁收缩的排查见 <a href="./../05-troubleshooting/chapter-02-isr-shrink.html">ISR 频繁收缩</a>。</p>`,16))])}const S=c(k,[["render",u]]);export{_ as __pageData,S as default};
